-- The race card and the expanded race step serve different reading contexts.
-- short_description is a mechanics-free one-line portrait for the card;
-- description is original long-form lore rendered below the selected card.
UPDATE dndshare.item_type
SET fields = fields || jsonb_build_array(jsonb_build_object(
    'name', 'Короткое описание',
    'key', 'short_description',
    'type', 'text'
))
WHERE id = 8
  AND jsonb_typeof(fields) = 'array'
  AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(fields) field
    WHERE field ->> 'key' = 'short_description'
  );

WITH race_lore(aliases, short_description, description) AS (
    VALUES
      (
        ARRAY['human', 'человек'],
        'Люди — молодой и беспокойный народ, который успевает за короткую жизнь изменить и себя, и окружающий мир.',
        '<p>Люди появляются повсюду: в шумных столицах и маленьких пограничных деревнях, среди мореплавателей, учёных, наёмников и земледельцев. Их обычаи меняются от края к краю, поэтому встреча двух людей из далёких земель порой напоминает встречу представителей разных народов.</p><p>Короткая жизнь приучает людей торопиться. Они строят города, основывают династии, отправляются за горизонт и берутся за замыслы, завершения которых могут не увидеть. Для одних это нетерпение, для других — редкая способность превращать мечту в действие.</p><p>Человеческого героя определяет не древнее наследие, а выбранный путь. Он может продолжать традицию семьи, бежать от неё или создать нечто совершенно новое — и именно эта свобода делает истории людей такими разными.</p>'
      ),
      (
        ARRAY['dwarf', 'дварф', 'дворф'],
        'Дварфы хранят память кланов, ценят честный труд и возводят дома, способные пережить века.',
        '<p>Под горными сводами и в каменных крепостях дварфы строят поселения, где имя мастера помнят так же долго, как имя короля. Камень, металл и огонь для них не просто ремесло: это язык, на котором одно поколение разговаривает со следующим.</p><p>Клан даёт дварфу историю, обязанности и круг тех, за кого он отвечает. Доверие здесь завоёвывают медленно, зато данное слово весит больше золота. Старые обиды тоже живут долго, особенно если за ними стоят утраченный дом или опозоренное имя.</p><p>Покидая родные чертоги, дварф редко забывает, откуда пришёл. В дороге он ищет достойное дело, утраченную реликвию, новый рынок для своего мастерства или ответ на вопрос, который не решился задать старейшинам.</p>'
      ),
      (
        ARRAY['elf', 'эльф'],
        'Эльфы воспринимают мир как долгую песню, в которой природа, магия и память звучат единым узором.',
        '<p>Эльфийские владения часто скрыты от торопливого взгляда: лесные тропы ведут мимо них, а башни словно растворяются в утреннем свете. Там искусство вплетено в повседневность, сады хранят следы веков, а песни рассказывают о событиях, которые для других народов стали легендой.</p><p>Долгая жизнь меняет чувство времени. Эльф может годами оттачивать одно умение, наблюдать, как меняются человеческие королевства, и всё же бережно хранить воспоминание о короткой встрече. За внешним спокойствием часто скрываются сильные привязанности и печали, которым тоже много лет.</p><p>Эльфы отправляются в путь из любопытства, долга или невозможности оставаться в стороне. Одни хотят увидеть, чем стал знакомый мир, другие охраняют древнюю тайну, а третьи впервые ищут жизнь, не написанную традициями их народа.</p>'
      ),
      (
        ARRAY['halfling', 'полурослик'],
        'Полурослики умеют ценить тихую радость дома, но в решающий момент находят мужество шагнуть далеко за его порог.',
        '<p>Для полурослика богатство начинается с надёжной крыши, полного стола и людей, которым можно доверять. Их поселения редко поражают величием, зато в них легко почувствовать себя гостем, а семейные истории пересказывают с такой любовью, будто речь идёт о великих сагах.</p><p>Спокойствие полуросликов не следует путать с беспечностью. Они внимательно замечают чужое настроение, умеют переждать бурю и не тратят силы на показную важность. Когда опасность приходит к друзьям, за привычной улыбкой обнаруживается удивительное упрямство.</p><p>Путешественник среди полуросликов может искать редкие блюда, новые истории или место, где его близким будет безопаснее. Даже в далёком подземелье он постарается устроить маленький островок уюта — и напомнить спутникам, ради чего стоит возвращаться.</p>'
      ),
      (
        ARRAY['gnome', 'гном'],
        'Гномы встречают мир с неугасимым любопытством и превращают каждую загадку в повод для нового опыта.',
        '<p>Гномьи дома полны незаконченных механизмов, записных книжек, коллекций странных камней и вещей, назначение которых хозяин непременно объяснит — если сумеет остановиться на одной теме. Для гнома почти любой предмет скрывает историю, а любая ошибка обещает интересное открытие.</p><p>Их весёлость не означает легкомыслия. За шутками часто стоит острый ум, который замечает необычные связи и находит выход там, где прямой путь закрыт. Гномы дорожат друзьями и охотно делятся восторгом, потому что хорошее открытие становится только лучше, когда его есть с кем обсудить.</p><p>В приключение гнома ведут тайна, редкое знание или простое желание увидеть невозможное своими глазами. Он может искать вдохновение для изобретения, след исчезнувшего наставника или ответ на вопрос, который всем остальным показался слишком странным.</p>'
      ),
      (
        ARRAY['halfelf', 'полуэльф'],
        'Полуэльфы живут между культурами и учатся превращать двойное наследие в собственный, ни на кого не похожий путь.',
        '<p>Полуэльф нередко растёт среди людей, для которых его молодость кажется необычно долгой, или среди эльфов, рядом с которыми годы всё равно бегут слишком быстро. Даже в любящей семье различие ощущается в мелочах: в шутках, привычках, ожиданиях и разговорах о будущем.</p><p>Жизнь между двумя мирами развивает внимательность к людям. Полуэльфы рано учатся менять манеру речи, понимать невысказанное и находить общий язык там, где стороны привыкли видеть только различия. Но умение быть своим повсюду иногда сопровождается вопросом, где находится настоящий дом.</p><p>Путешествие даёт возможность ответить на него самостоятельно. Кто-то становится посредником между народами, кто-то собирает вокруг себя новую семью, а кто-то отказывается выбирать одну половину наследия и строит судьбу, в которой обе звучат на равных.</p>'
      ),
      (
        ARRAY['halforc', 'полуорк'],
        'Полуорки несут заметное наследие двух народов, но свою честь, ярость и верность определяют собственными поступками.',
        '<p>Происхождение полуорка часто замечают раньше, чем его самого. Незнакомцы могут ждать грубости, силы или вспыльчивости, не пытаясь узнать человека перед собой. Поэтому многие полуорки рано понимают цену самообладания — или решают не тратить жизнь на чужие ожидания.</p><p>Сильные чувства для них не обязательно означают жестокость. Ярость может стать защитой слабых, гордость — опорой перед унижением, а преданность — обещанием, которое невозможно сломать. Среди тех, кто принимает их без предубеждения, полуорки нередко оказываются самыми надёжными товарищами.</p><p>В дорогу их ведёт желание доказать что-то миру, семье или самим себе. Один ищет славу, другая — место без старых ярлыков, третий хочет примирить общины, каждая из которых привыкла считать его чужаком.</p>'
      ),
      (
        ARRAY['dragonborn', 'драконорожденный'],
        'Драконорождённые гордятся древним обликом, дорожат именем рода и стремятся быть достойными собственных клятв.',
        '<p>Драконорождённого трудно не заметить: чешуя, величественная осанка и черты далёких драконьих предков выделяют его в любой толпе. Но для него самого важнее не впечатление, которое производит внешность, а поступки, способные принести честь или бесчестье всему роду.</p><p>Обещание имеет особый вес. Драконорождённые уважают мастерство, ответственность и готовность отвечать за выбор, даже когда цена оказывается высокой. Соперничество они могут воспринимать как способ стать лучше, а поражение — как урок, который нельзя оставлять невыученным.</p><p>Герой отправляется в путь, чтобы исполнить клятву, вернуть доброе имя, превзойти знаменитого предка или понять, кем он является вне ожиданий клана. За суровой собранностью нередко скрывается желание найти тех, перед кем можно не доказывать своё достоинство каждый день.</p>'
      ),
      (
        ARRAY['tiefling', 'тифлинг'],
        'Тифлинги носят на лице печать далёкого инфернального наследия, но смысл своей жизни выбирают сами.',
        '<p>Рога, хвост и необычный взгляд делают происхождение тифлинга очевидным, хотя за внешними признаками могут стоять совершенно разные семейные истории. Чужой страх часто возникает раньше знакомства, и потому тифлинги привыкают читать настроение комнаты ещё до первого слова.</p><p>Одни отвечают на предубеждение сдержанностью, другие — дерзким юмором или нарочитой независимостью. Почти каждому приходится провести границу между унаследованным образом и собственной личностью. Доверие для них особенно ценно, потому что оно редко бывает случайным.</p><p>Приключение может стать бегством от прошлого, поиском происхождения или заявлением о себе миру. Тифлинг способен принять мрачную символику своего облика, отвергнуть её или превратить в оружие против тех, кто судит только по внешности.</p>'
      )
)
UPDATE dndshare.item race
SET data = jsonb_set(
    jsonb_set(race.data, '{short_description}', to_jsonb(lore.short_description), true),
    '{description}', to_jsonb(lore.description), true
)
FROM race_lore lore
WHERE race.user_id IS NULL
  AND race.parent_id IS NULL
  AND race.type_id = 8
  AND jsonb_typeof(race.data) = 'object'
  AND (
    regexp_replace(replace(lower(COALESCE(race.name_en, '')), 'ё', 'е'), '[^a-zа-я0-9]+', '', 'g') = ANY(lore.aliases)
    OR regexp_replace(replace(lower(race.name), 'ё', 'е'), '[^a-zа-я0-9]+', '', 'g') = ANY(lore.aliases)
  );
